{
  "root": "main",
  "state": {
    "contractPoints": [
      {
        "Area": "Scope of work",
        "Confirm": "Exact deliverables list",
        "Risk": "Scope creep",
        "Position": "Define exclusions"
      },
      {
        "Area": "Deposit",
        "Confirm": "50% upfront",
        "Risk": "Unpaid work",
        "Position": "No start until paid"
      },
      {
        "Area": "Revisions",
        "Confirm": "2 rounds max",
        "Risk": "Unlimited feedback",
        "Position": "Bill extra rounds"
      },
      {
        "Area": "Ownership",
        "Confirm": "Transfer after payment",
        "Risk": "Unauthorized use",
        "Position": "Retain copyright"
      },
      {
        "Area": "Timeline",
        "Confirm": "Milestones and deadlines",
        "Risk": "Slow feedback",
        "Position": "Pause project if late"
      }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": ["header", "intro", "table", "negotiation", "email_title", "email_body", "email_sig", "actions"]
    },
    "header": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "sm", "align": "center" },
      "children": ["title"]
    },
    "title": { "type": "Text", "props": { "text": "Freelance Design Contract Checklist", "variant": "h1" }, "children": [] },
    "intro": { "type": "Text", "props": { "text": "Use this checklist to protect your $4,500 logo project. Focus on payment, revisions, and ownership timing.", "variant": "body" }, "children": [] },
    "table": {
      "type": "Table",
      "props": {
        "domain": "generic",
        "preferredPresentation": "cards",
        "statePath": "/contractPoints",
        "columns": [
          { "key": "Area", "label": "Area" },
          { "key": "Confirm", "label": "Confirm" },
          { "key": "Risk", "label": "Risk" },
          { "key": "Position", "label": "Position" }
        ]
      },
      "children": []
    },
    "negotiation": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": [
        { "type": "Text", "props": { "text": "Negotiation Approach", "variant": "h2" }, "children": [] },
        { "type": "Text", "props": { "text": "Reframe policies as standard practice. Offer compromises, not concessions.", "variant": "body" }, "children": [] }
      ]
    },
    "email_title": { "type": "Text", "props": { "text": "Client-Friendly Script", "variant": "h2" }, "children": [] },
    "email_body": { "type": "Text", "props": { "text": "Hi Client, I am excited to move forward. To ensure we are aligned, I have outlined standard terms: 50% deposit, 2 revision rounds, and ownership transfer upon final payment. This protects our timeline and prevents scope creep.", "variant": "body" }, "children": [] },
    "email_sig": { "type": "Text", "props": { "text": "Best, Designer", "variant": "label" }, "children": [] },
    "actions": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "md" },
      "children": ["btn1"]
    },
    "btn1": { "type": "Button", "props": { "label": "Review Legal Resources", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.canada.ca/en/services/business.html" } } } }, "children": [] }
  }
}
